package org.peirs.model;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant;
@Entity @Table(name="evaluations",uniqueConstraints=@UniqueConstraint(columnNames={"project_id","evaluator_id"})) public class Evaluation { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @ManyToOne(optional=false) @JoinColumn(name="project_id") public Project project; @ManyToOne(optional=false) @JoinColumn(name="evaluator_id") public User evaluator; @Column(name="overall_score",nullable=false) public BigDecimal overallScore; @Column(name="financial_score",nullable=false) public BigDecimal financialScore; @Column(name="risk_score",nullable=false) public BigDecimal riskScore; @Column(columnDefinition="text") public String comments; @Column(name="created_at",insertable=false,updatable=false) public Instant createdAt; }
